"""
import json, sys, html as _h

BOOK = {'title': 'Prometheus and Pandora', 'author': 'Traditional (Greek myth)', 'genre': 'Greek Myths and Legends', 'chapters': [{'n': 1, 'title': 'Complete Text', 'text': "In the beginning, the Titan Prometheus, whose name means Forethought, shaped men from earth and water, and taught them all the arts. But Zeus, king of the gods, kept fire from mortals. Prometheus stole fire, hiding a spark in a fennel stalk, and brought it to men. Zeus, in anger, chained Prometheus to a rock in the Caucasus, where an eagle tore his liver each day, and each night it healed — until Hercules freed him. To punish men, Zeus ordered Hephaestus to fashion Pandora, the first woman, beautiful and cunning, and each god gave her a gift. She was given to Epimetheus, Prometheus's brother, though Prometheus had warned him to accept nothing from Zeus. With her came a sealed jar. Curiosity overcame her; she opened it, and out flew all the evils — sickness, sorrow, toil, and strife — scattering over the world. She closed the lid just in time to keep Hope inside. And so men have evils, but also hope, to this day."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

